check:
{v:'VER',what:'the what is new card is stamped within 0.15 of the build',
 run:function(){
   if(typeof WHATSNEW_VER==='undefined'||typeof VER==='undefined') return 'SKIP: this build has no what is new card';
   if(parseFloat(WHATSNEW_VER)>33.63+0.001) return 'SKIP: the card has moved on, a later card check covers it';
   var d=parseFloat(VER)-parseFloat(WHATSNEW_VER);
   return d<=0.15+1e-9?null:'the card is stamped v'+WHATSNEW_VER+', '+d.toFixed(2)+' behind v'+VER; }},
